                if (direction !== 0) text += direction > 0 ? '^' : 'v';
                ctx.fillText(text, 128, 128);
                tex.needsUpdate = true;
            }
        };

        return indicatorGroup;
    }

    // Helper to add neighbor relationships
    function Vector3WithNeighbors(x, y, z) {
        this.x = x;
        this.y = y;
        this.z = z;
        this.neighbors = [];
        this.addNode = function(name) {
