        // Build floors and walls
        for (let floorNum = 0; floorNum < WORLD.FLOOR_COUNT; floorNum++) {
            const floorY = floorNum * WORLD.FLOOR_HEIGHT;
            const floorData = buildFloor(floorNum, floorY, shaftCenterX, shaftCenterZ);
